insert into public.content_items(id,type,slug,data) values ('a02','article','kayfa-naqra-nusus','{"id":"a02","slug":"kayfa-naqra-nusus","type":"article","title":"كيف نقرأ النصوص الدينية بموضوعية؟","description":"مقال تجريبي لعرض تجربة القراءة الطويلة في الموقع.","thumbnailUrl":null,"authorName":"معاذ عليان","categoryIds":["texts"],"tags":["منهج"],"publishedAt":null,"sourceUrl":null,"featured":false,"verified":false,"demo":true,"rightsStatus":"unknown","body":"هذا المقال **محتوى تجريبي** وُضع لعرض تجربة القراءة في الموقع فقط، ولا يمثل نصًا منشورًا حقيقيًا.\n\n## لماذا تهم الموضوعية؟\n\nالموضوعية في قراءة النصوص الدينية تعني البحث عن معنى النص في سياقه، لا في افتراضاتنا المسبقة عنه. ويحتاج القارئ إلى أدوات واضحة تمكنه من التمييز بين النص وشرحه.\n\n## خطوات عملية\n\n1. تحديد سياق النص: من قالها؟ ومتى؟ ولمن؟\n2. النظر إلى النسخ والترجمات المتوفرة ومقارنة الفروق.\n3. جمع أقوال المفسّرين المختلفين قبل الحكم.\n4. صياغة نتيجة محدودة بما وُجد من الأدلة.\n\n## خاتمة\n\nالغاية ليست الفوز في جدال، بل الاقتراب من فهم أدق. وهذه الخطوات قابلة للتطبيق على أي نص ديني يدرسه القارئ.","readingTimeMinutes":4}'::jsonb) on conflict (id) do nothing;
insert into public.content_items(id,type,slug,data) values ('a03','article','manhaj-alradd-ala-shubuhat','{"id":"a03","slug":"manhaj-alradd-ala-shubuhat","type":"article","title":"منهجية الرد على الشبهات: خمس خطوات","description":"مقال تجريبي يعرض منهجًا مقترحًا للتعامل مع الشبهات.","thumbnailUrl":null,"authorName":"معاذ عليان","categoryIds":["responses"],"tags":["منهج"],"publishedAt":null,"sourceUrl":null,"featured":false,"verified":false,"demo":true,"rightsStatus":"unknown","body":"هذا المقال **محتوى تجريبي** وُضع لعرض تجربة القراءة في الموقع فقط، ولا يمثل نصًا منشورًا حقيقيًا.\n\n## لماذا نحتاج منهجًا؟\n\nالتعامل مع الشبهات بردود متسرعة يفتح باب اللبس. المنهج يجعل الرد أقرب إلى البحث منه إلى الجدال.\n\n## الخطوات الخمس\n\n1. **نقل الشبهة بأمانة**: بنص كامل ومصدرها.\n2. **فهم مقصودها**: ما السؤال الحقيقي المطروح؟\n3. **جمع الأدلة**: من النصوص والمصادر الموثوقة.\n4. **صياغة الرد**: بلغة واضحة بلا مبالغة.\n5. **مراجعة الرد**: هل يجيب عن الشبهة نفسها فعلًا؟\n\n## خلاصة\n\nالرد الجيد يبدأ بالإنصاف، وينتهي بالوضوح لا بالاستعراض.","readingTimeMinutes":3}'::jsonb) on conflict (id) do nothing;
